import json,subprocess,sys
sys.path.insert(0,'/workspace')
def run(obj, cls='/workspace/tmp/classes'):
    data=json.dumps(obj).encode()
    r=subprocess.run(['python3','/workspace/run.py',cls],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=180)
    if r.returncode!=0:
        print('EXIT',r.returncode,r.stderr.decode()[:3000]); return None
    return json.loads(r.stdout.decode())

def brief(res):
    if res is None: return
    if 'error' in res: print('ERROR', res['error']); return
    for t in res['traces']:
        for p in t['packets']:
            print('  pkt e%d/%d off%d %s pn=%s ep=%s %s %s' % (p['event'],p['packet'],p['offset'],p['level'],p['pn'],p['epoch'],p['status'],(p['sha256'] or '')[:12]))
        for d in t['datagrams']:
            print('  dg e%d n=%d acc=%d bytes=%d %s' % (d['event'],d['packets'],d['accepted'],d['bytes'],d['sha256'][:12]))
        print('  closed=%s keys=%s received=%s epoch=%s epochs=%s' % (t['closed'],t['keys'],t['received'],t['key_epoch'],t['epochs']))
        print('  opened=%s used=%d smd=%d sms=%s' % (t['opened'],t['used'],t['send_max_data'],t['send_max_streams']))
        for s in t['streams']:
            print('  stream id=%d high=%d final=%s reset=%s stop=%s sendmax=%d ranges=%s uniq=%d pre=%d %s' % (s['id'],s['high'],s['final'],s['reset'],s['stop'],s['send_max'],s['ranges'],s['unique'],s['prefix'],s['sha256'][:12]))
        for c in t['crypto']:
            if c['unique'] or True:
                print('  crypto %s ranges=%s uniq=%d pre=%d %s' % (c['level'],c['ranges'],c['unique'],c['prefix'],c['sha256'][:12]))
        for a in t['acknowledged']:
            print('  ack %s count=%d intervals=%d prefix=%d %s ecn=%s' % (a['level'],a['count'],a['intervals'],a['prefix'],a['sha256'][:12],a['ecn']))
        print('  peer_cids=%s rpt=%d retired=%s' % (t['peer_cids'],t['retire_prior_to'],t['retired_local']))

def show(obj, compact=True):
    r=run(obj)
    if compact: brief(r)
    else: print(json.dumps(r,indent=1))
    return r
